<?php require 'common.php'; $mode=lab_mode(); $message=''; if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['login'])){if($mode==='fixed'){session_regenerate_id(true);$_SESSION['lab_auth']=true;$_SESSION['authenticated_at']=time();$message='200 OK: authenticated + session ID regenerated.';}else{$_SESSION['lab_auth']=true;$message='200 OK: vulnerable demo keeps the existing session ID.';}audit('Session Fixation',$mode,'POST','/security-lab/session.php',200,'authenticated',$message);} if(isset($_GET['logout'])){$_SESSION=[];if(ini_get('session.use_cookies')){ $p=session_get_cookie_params();setcookie(session_name(),'',['expires'=>time()-42000,'path'=>$p['path'],'domain'=>$p['domain'],'secure'=>$p['secure'],'httponly'=>$p['httponly'],'samesite'=>$p['samesite']??'Lax']);}session_destroy();session_start();$message='Logged out and session cleared.';} ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Session Lab</title></head><body style="font-family:Arial;max-width:900px;margin:30px auto"><h1>Session Fixation / Session Security Lab</h1><p>Mode: <b><?=h($mode)?></b></p><p>Session ID: <code><?=h(session_id())?></code></p><p>Authenticated: <b><?=!empty($_SESSION['lab_auth'])?'YES':'NO'?></b></p><form method="post"><button name="login" value="1">Login demo</button></form><p><?=h($message)?></p><p>Fixed: regenerate session ID after authentication, Secure/HttpOnly/SameSite cookie flags, timeout and complete logout.</p><a href="?logout=1">Logout / reset session</a> · <a href="index.php">Lab menu</a></body></html>